<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Support\LegacyResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Throwable;
class ShiftMonitoringController extends Controller
{
 private function user(Request $r){return $r->attributes->get('jwt_user');}
 public function all(Request $r){try{$q=DB::table('equipment')->where('active',true);if($r->filled('plant'))$q->where('plant',$r->input('plant'));if($r->filled('department'))$q->where('department',$r->input('department'));$eqs=$q->orderBy('department')->orderBy('name')->get();$out=[];foreach($eqs as $e){$x=['id'=>$e->id,'code'=>$e->code,'name'=>$e->name,'department'=>$e->department,'location'=>$e->location,'plant'=>$e->plant,'hourly_entry'=>(bool)$e->hourly_entry];$x['monitoring']=DB::table('equipment_monitoring_params')->select('id','parameter_name','standard_value','unit','display_order','columns','is_dynamic','user_boxes')->where('equipment_id',$e->id)->where('is_active',true)->orderBy('display_order')->orderBy('id')->get()->map(fn($p)=>LegacyResponse::normalize($p))->all();$out[]=$x;}return response()->json(['success'=>true,'data'=>$out]);}catch(Throwable $e){return $this->err($e);}}
 public function today(Request $r){try{$q=DB::table('shift_monitoring_logs as pl')->join('equipment as e','e.id','=','pl.equipment_id')->select('pl.equipment_id','pl.hour_number','e.hourly_entry')->where('pl.shift',$r->input('shift'))->whereDate('pl.logged_at',now()->toDateString());if($r->filled('plant'))$q->where('e.plant',$r->input('plant'));if($r->filled('department'))$q->where('e.department',$r->input('department'));$rows=$q->get();$map=[];foreach($rows as $x){$key=(string)$x->equipment_id;if(!isset($map[$key]))$map[$key]=['submitted'=>false,'submitted_hours'=>[]];if($x->hourly_entry&&$x->hour_number){$h=(int)$x->hour_number;if(!in_array($h,$map[$key]['submitted_hours'],true))$map[$key]['submitted_hours'][]=$h;if(count($map[$key]['submitted_hours'])>=8)$map[$key]['submitted']=true;}elseif(!$x->hourly_entry)$map[$key]['submitted']=true;}return response()->json(['success'=>true,'data'=>$map]);}catch(Throwable $e){return $this->err($e);}}
 public function log(Request $r){$plant=$r->input('plant');$dept=$r->input('department');$shift=$r->input('shift');$eid=$r->input('equipment_id');$hour=$r->input('hour_number');$entries=$r->input('entries');if(!$plant||!$shift||!$eid||!is_array($entries)||!count($entries))return response()->json(['success'=>false,'message'=>'plant, shift, equipment_id, entries required'],400);if($hour!==null){$h=(int)$hour;if($h<1||$h>8)return response()->json(['success'=>false,'message'=>'hour_number must be 1–8'],400);}try{if($dept!=='Process'){$dup=DB::table('shift_monitoring_logs')->where('equipment_id',$eid)->where('shift',$shift)->whereDate('logged_at',now()->toDateString())->where(function($q)use($hour){if($hour===null)$q->whereNull('hour_number');else$q->where('hour_number',(int)$hour);})->exists();if($dup)return response()->json(['success'=>false,'message'=>'Parameters for '.($hour?'Hour '.$hour:'this shift').' already submitted.'],409);} $readings=[];foreach($entries as $e){$std=$e['standard_value_snapshot']??null;$actual=$e['actual_value']??null;$status=!$std?'RECORDED':((string)$actual===(string)$std?'OK':'DEVIATION');$readings[]=['parameter_id'=>$e['parameter_id']??null,'standard_value_snapshot'=>$std?:null,'actual_value'=>$actual,'status'=>$status,'remarks'=>($e['remarks']??null)?:null];}$id=DB::table('shift_monitoring_logs')->insertGetId(['equipment_id'=>$eid,'plant'=>$plant,'department'=>$dept?:null,'shift'=>$shift,'hour_number'=>$hour!==null?(int)$hour:null,'logged_by'=>$this->user($r)->id,'readings'=>json_encode($readings),'logged_at'=>now()]);return response()->json(['success'=>true,'data'=>['id'=>$id]]);}catch(Throwable $e){return $this->err($e);}}
 public function byEquipment($eqId){try{$rows=DB::table('equipment_monitoring_params')->select('id','equipment_id','parameter_name','standard_value','unit','display_order','columns','is_dynamic','user_boxes')->where('equipment_id',$eqId)->where('is_active',true)->orderBy('display_order')->orderBy('id')->get()->map(fn($x)=>LegacyResponse::normalize($x))->all();return response()->json(['success'=>true,'data'=>$rows]);}catch(Throwable $e){return $this->err($e);}}
 public function createParam(Request $r,$eqId){if(!$r->input('parameter_name'))return response()->json(['success'=>false,'message'=>'parameter_name required'],400);try{$id=DB::table('equipment_monitoring_params')->insertGetId(['equipment_id'=>$eqId,'plant'=>$r->input('plant'),'department'=>$r->input('department'),'parameter_name'=>$r->input('parameter_name'),'standard_value'=>$r->input('standard_value')?:null,'unit'=>$r->input('unit')?:null,'display_order'=>$r->input('display_order',1),'columns'=>json_encode($r->input('columns',[])),'is_dynamic'=>$r->boolean('is_dynamic'),'user_boxes'=>json_encode($r->input('user_boxes',[])),'is_active'=>true,'created_at'=>now()]);return response()->json(['success'=>true,'data'=>['id'=>$id]]);}catch(Throwable $e){return $this->err($e);}}
 public function updateParam(Request $r,$id){try{$data=[];foreach(['parameter_name','display_order'] as $k)if($r->has($k))$data[$k]=$r->input($k);foreach(['standard_value','unit'] as $k)if($r->has($k))$data[$k]=$r->input($k)?:null;if($r->has('columns'))$data['columns']=json_encode($r->input('columns',[]));if($r->has('is_dynamic'))$data['is_dynamic']=$r->boolean('is_dynamic');if($r->has('user_boxes'))$data['user_boxes']=json_encode($r->input('user_boxes',[]));if(!$data)return response()->json(['success'=>true,'message'=>'No fields to update']);DB::table('equipment_monitoring_params')->where('id',$id)->update($data);return response()->json(['success'=>true]);}catch(Throwable $e){return $this->err($e);}}
 public function deleteParam($id){try{DB::table('equipment_monitoring_params')->where('id',$id)->update(['is_active'=>false]);return response()->json(['success'=>true]);}catch(Throwable $e){return $this->err($e);}}
 public function last24(Request $r){try{$q=DB::table('shift_monitoring_logs as pl')->join('equipment as e','e.id','=','pl.equipment_id')->join('users as u','u.id','=','pl.logged_by')->select('pl.id','pl.equipment_id','e.name as equipment_name','e.code as equipment_code','e.department','e.hourly_entry','pl.shift','pl.hour_number','pl.readings','pl.logged_at','u.full_name as logged_by_name','u.department as logged_by_dept')->where('pl.logged_at','>=',now()->subHours(24));if($r->filled('plant'))$q->where('e.plant',$r->input('plant'));if($r->filled('department'))$q->where('e.department',$r->input('department'));return response()->json(['success'=>true,'data'=>$q->orderByDesc('pl.logged_at')->get()->map(fn($x)=>LegacyResponse::normalize($x))->all()]);}catch(Throwable $e){return $this->err($e);}}
 private function err(Throwable $e){return response()->json(['success'=>false,'message'=>$e->getMessage()],500);}
}
